CASE = {'id': 'I4', 'title': 'Atomic legacy SQLite migration', 'difficulty': 4, 'prompt': "Implement app/store.py using Python stdlib only. Only app/ may change. API: migrate(path: str, fault=None) -> None and read_items(path: str) -> list[tuple[int,str]]. Legacy DB has PRAGMA user_version=0 and CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL), with arbitrary ids/values. New version is user_version=1; items must have columns id INTEGER PRIMARY KEY, value TEXT NOT NULL, normalized TEXT NOT NULL. normalized is value.strip().lower(); read_items returns (id,normalized) ordered by id. Migration preserves id and original value. Accept an empty DB by creating new schema/version. Reopening already migrated version 1 is a no-op, with no fault hook calls. Reject versions >1 via ValueError without mutations. Migration must be one SQLite transaction (including DDL and version), close its connection, and roll back entirely on any exception. During legacy conversion call fault('after_copy') after copying rows to replacement table but before removing old table, and fault('before_commit') after schema/version changes but before commit, if fault is provided; propagate hook errors. A later retry must succeed with no temporary tables remaining. read_items only reads migrated DB and closes connection. No external dependencies.", 'starter': {'app/__init__.py': '', 'app/store.py': 'def migrate(path, fault=None):\n    pass\n\ndef read_items(path):\n    return []\n', 'test_public.py': "import tempfile,os,unittest\nfrom app.store import migrate,read_items\nclass PublicTests(unittest.TestCase):\n    def test_new_db(self):\n        with tempfile.TemporaryDirectory() as d:\n            p=os.path.join(d,'db');migrate(p);self.assertEqual(read_items(p),[])\n"}, 'reference': {'app/store.py': 'import sqlite3\n\ndef migrate(path, fault=None):\n    c=sqlite3.connect(path)\n    try:\n        c.execute(\'BEGIN IMMEDIATE\')\n        version=c.execute(\'PRAGMA user_version\').fetchone()[0]\n        if version>1:\n            raise ValueError(\'unsupported version\')\n        if version==1:\n            c.rollback()\n            return\n        exists=c.execute("SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=\'items\'").fetchone()\n        c.execute(\'CREATE TABLE items_new(id INTEGER PRIMARY KEY,value TEXT NOT NULL,normalized TEXT NOT NULL)\')\n        if exists:\n            rows=c.execute(\'SELECT id,value FROM items\').fetchall()\n            c.executemany(\'INSERT INTO items_new VALUES(?,?,?)\',[(i,v,v.strip().lower()) for i,v in rows])\n        if fault:\n            fault(\'after_copy\')\n        if exists:\n            c.execute(\'DROP TABLE items\')\n        c.execute(\'ALTER TABLE items_new RENAME TO items\')\n        c.execute(\'PRAGMA user_version=1\')\n        if fault:\n            fault(\'before_commit\')\n        c.commit()\n    except BaseException:\n        c.rollback()\n        raise\n    finally:\n        c.close()\n\ndef read_items(path):\n    c=sqlite3.connect(path)\n    try:\n        return c.execute(\'SELECT id,normalized FROM items ORDER BY id\').fetchall()\n    finally:\n        c.close()\n'}, 'private_tests': {'test_private.py': 'import os,sqlite3,tempfile,unittest\nfrom app.store import migrate,read_items\nclass MigrationTests(unittest.TestCase):\n    def setUp(self):\n        self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup);self.p=os.path.join(self.tmp.name,\'db\')\n    def legacy(self,rows=((8,\' Foo \'),(-2,\'BÄR\'))):\n        with sqlite3.connect(self.p) as c:\n            c.execute(\'CREATE TABLE items(id INTEGER PRIMARY KEY,value TEXT NOT NULL)\');c.executemany(\'INSERT INTO items VALUES(?,?)\',rows)\n    def state(self):\n        with sqlite3.connect(self.p) as c:\n            return c.execute(\'PRAGMA user_version\').fetchone()[0],c.execute(\'SELECT * FROM items ORDER BY id\').fetchall(),c.execute("SELECT name FROM sqlite_master WHERE type=\'table\' ORDER BY name").fetchall()\n    def test_empty_database(self):\n        migrate(self.p);self.assertEqual(read_items(self.p),[]);self.assertEqual(self.state()[0],1)\n    def test_preserves_values_and_ids(self):\n        self.legacy();migrate(self.p);self.assertEqual(self.state()[1],[(-2,\'BÄR\',\'bär\'),(8,\' Foo \',\'foo\')])\n    def test_unicode_normalization(self):\n        self.legacy([(1,\'  ÉCOLE  \'),(2,\'\')]);migrate(self.p);self.assertEqual(read_items(self.p),[(1,\'école\'),(2,\'\')])\n    def test_order(self):\n        self.legacy([(99,\'Z\'),(1,\'A\')]);migrate(self.p);self.assertEqual(read_items(self.p),[(1,\'a\'),(99,\'z\')])\n    def test_idempotent(self):\n        self.legacy();migrate(self.p);before=self.state();migrate(self.p,lambda _:self.fail(\'hook called\'));self.assertEqual(self.state(),before)\n    def rollback_at(self,point):\n        self.legacy();before=self.state()\n        def fault(stage):\n            if stage==point:raise RuntimeError(\'injected\')\n        with self.assertRaisesRegex(RuntimeError,\'injected\'):migrate(self.p,fault)\n        self.assertEqual(self.state(),before);migrate(self.p);self.assertEqual(len(read_items(self.p)),2)\n    def test_rollback_after_copy(self):self.rollback_at(\'after_copy\')\n    def test_rollback_before_commit(self):self.rollback_at(\'before_commit\')\n    def test_hooks_in_order(self):\n        self.legacy();calls=[];migrate(self.p,calls.append);self.assertEqual(calls,[\'after_copy\',\'before_commit\'])\n    def test_future_version_unchanged(self):\n        self.legacy()\n        with sqlite3.connect(self.p) as c:c.execute(\'PRAGMA user_version=7\')\n        before=self.state()\n        with self.assertRaises(ValueError):migrate(self.p)\n        self.assertEqual(self.state(),before)\n    def test_empty_legacy(self):\n        self.legacy([]);migrate(self.p);self.assertEqual(self.state(),(1,[],[(\'items\',)]))\n'}}
